import{Ka as c}from"./chunk-Z6LLB6LC.js";import"./chunk-TZBLDSUG.js";import{d as u}from"./chunk-LM6XNZSS.js";import"./chunk-OD6DHY7Z.js";import{f as l}from"./chunk-6YBVR5FR.js";import{k as s}from"./chunk-PFGE6SJW.js";var t=e=>e.map(o=>`<li>${o}</li>`).join(""),b=(e,o,i=!1)=>`<details class="about-sec" ${i?"open":""}><summary>${e}</summary><div class="about-body">${o}</div></details>`;function f(){let e=c.mode==="cloud",o=(window.SISTER_APPS||[]).filter(a=>a.id!=="home-pantry"),i=[["🗓️",s("今日"),s("首页。把储藏、房屋、设备、账单、交易、车辆各处要做的事，按“紧急 / 今天 / 尽快 / 留意”四档合在一张注意事项里；可按房产分组、只看要紧的、只看我负责的。勾选框类的事（季节任务、交易清单）直接在首页勾。首页还有“咩咩咩”和常用快捷入口。")],["🗄️",s("储藏"),s("厨房与日用品库存：数量、位置、少货线、保质期；点 −/+ 记消耗，少货和临期自动提醒并进购物车。试过不好吃、暂时不想补的，点“不再提醒”就不会一直出现在注意事项里。家居耐用品（床品、电器、自行车、工具）只记数量和位置。“菜单”可以让 AI 按现有库存配菜，入库越久的越优先用掉。")],["🏠",s("房屋"),s("房屋资料（房型、设施、材料、地址、保险、HOA / 物业）→ 谁负责维护、材料保养建议、推荐耗材；设备档案与保养记录；按月的季节任务；车辆档案与保养时间表；买房 / 卖房 / 退租的交易清单。多套房产可切换。")],["🧾",s("账单"),s("周期性账单（水电气网、HOA、房产税、房贷房租、保险、车贷、信用卡、订阅）：自动算下次到期，提前提醒，自动扣款的提示核对。一次性账单（医疗、宠物、法律税务、装修）：有总额、可分次付、看余额。还有预算和花费统计，可导出到手机日历。只存付款方、账号尾号和缴费链接，不存密码。")],["🛒",s("采购"),s("一张全家共用的购物车：少货自动加入、手动加、认领“我来买”、买到后自动加回库存并记花费。“录入购物”可以拍小票或粘贴线上订单，AI 读成清单后一键入库。")],["👤",s("我的"),s("库存使用趋势、年度 CSV；设置里管家庭成员与名册（大人、孩子、宠物）、邀请码、房产、语言与单位、模块开关、AI 助手、通知与备份。")]];return`
    <section class="section about">
      <div class="section-head"><h2>${s("爱家小助手")} · ${s("介绍")}</h2><p>${s("一个家，一份清单，家人共同维护")}</p></div>
      <div class="panel about-intro">
        <p>${s("「爱家小助手」帮一家人把过日子要记的事放在一处：厨房和日用品还有多少、房子哪些部位该检修、设备保养到期没、账单什么时候交、车该做什么保养、买房卖房要走哪些步骤。所有数据挂在同一个“家庭”下，家人用邀请码加入后看到的是同一份，谁改了什么都能看到。")}</p>
        <p class="muted">${e?s("你现在是云端协同版：家人修改会实时同步。"):s("你现在是本地演示版：数据只保存在这个浏览器里，换设备或清缓存就没了；部署 Supabase 后才能家人共享。")}</p>
      </div>

      ${b(s("六个入口各管什么"),`<ul class="about-modules">${i.map(([a,n,p])=>`<li><span class="about-ico" aria-hidden="true">${a}</span><div><b>${n}</b><p>${p}</p></div></li>`).join("")}</ul>`,!0)}

      ${b(s("第一次使用建议这样做"),`<ol class="about-steps">${t([s("<b>我的 → 设置</b>：确认语言、地区与单位（美制 / 公制、货币）；需要的话关掉用不到的模块。"),s("<b>房屋 → 房屋资料</b>：选地区、房型、设施、材料，填地址、保险、HOA。这一步决定后面推荐什么耗材、生成哪些设备、每月有什么季节任务。"),s("<b>房屋 → 设备</b>：按资料一键生成，再补品牌、安装年份、保修；<b>房屋 → 车辆</b> 加上家里的车。"),s("<b>财务 → 常用账单</b>：按模板一次建好，再补金额和到期日；自动扣款的勾上“自动扣款”。"),s("<b>储藏</b>：先加常用的十几样，设少货线；之后每次用完点 −，补货点 +。也可以用“录入购物”拍小票批量入库。"),s("<b>设置 → 家庭与成员</b>：核对家人名册（大人、孩子、宠物），医疗和宠物账单会用到；想用 AI 的话在 <b>设置 → AI 助手</b> 填 key（可选）。"),s("<b>设置 → 邀请码</b>：发给家人，他们在登录页输入邀请码直接进入。")])}</ol>`)}

      ${b(s("提醒是怎么分级的"),`<ul class="about-levels">${[["b-out",s("紧急"),s("已经逾期的账单、逾期的“必须”交易任务")],["b-low",s("今天"),s("今天到期的账单、设备保养逾期、过期的保险 / 牌照 / 排放")],["b-soon",s("尽快"),s("一周内到期、待核对的自动扣款、缺货、已过期的食材、检查发现需维修、30 天内到期的保险 / 牌照 / 排放、本月花费超预算")],["b-ok",s("留意"),s("少货、即将告罄、临期、本月季节任务、租赁与保修快到期、预算快用完")]].map(([a,n,p])=>`<li><span class="badge ${a}">${n}</span><span>${p}</span></li>`).join("")}</ul>
      <p class="muted">${s("网页标题上的数字只算前三档。不想补货的物品可以标“不再提醒”（只影响缺货 / 少货 / 即将告罄，临期照常）。打开过网页的浏览器可以开通知；账单还能导出到手机日历，由系统响铃，不依赖网页是否打开。")}</p>`)}

      ${b(s("咩咩咩与 AI 菜单助手"),`<ul class="about-notes">${t([s("<b>咩咩咩</b>：首页的“咩咩咩”可以问家里任何事——保养、账单、买卖房、清洁收纳、带娃；可选附带家里的情况（不含备注和个人信息）。"),s("<b>AI 菜单助手</b>在 储藏 → 菜单：按现有库存配三餐，先用临期的，再按入库先后做掉放得最久的；有“哺乳期追奶”“产后恢复”等快捷要求，缺的食材可一键加入购物车。"),s("<b>没填 key 也能用</b>：会生成提示词，复制到豆包、千问、ChatGPT 等粘贴即可；填了 API key（设置 → AI 助手）就能直接出结果，有免费模型可选。"),s("<b>发给模型的只有</b>食材名、数量、单位、入库和临期天数，以及你写的问题；API key 只存在这台设备的浏览器里。AI 的回答仅供参考，过敏和慢病饮食以医生建议为准。")])}</ul>`)}

      ${b(s("注意事项"),`<ul class="about-notes">${t([s("<b>不要存密码和完整卡号。</b>账单只记付款方、账号尾号、登录提示和缴费链接；保险只记保单号和保障范围摘要。"),s("<b>邀请码就是这个家的钥匙。</b>发给家人就够了，别贴到公开的地方；泄露了请家主在设置里“重置邀请码”，旧码立即失效。"),s("<b>用邀请码直接进入的家人</b>身份存在那台设备的浏览器里，清除浏览器数据或换手机后要重新用邀请码进入。"),s("<b>一个人用了多个浏览器或设备</b>，每个都会算一位家人。加入后如果和已有成员同名，会推荐“爸爸#2”“爸爸 10/22”这样的称呼；是同一个人的话也可以保持不变，之后在 设置 → 家庭与成员 里随时改。"),s("<b>寿命、保养周期、费用区间都是常见经验值</b>（芝加哥地区行情），以设备说明书、当地气候和专业人士检查为准；涉及燃气、电、屋顶、高处作业请找专业人员。"),s("<b>买卖流程和停服务时间</b>按伊利诺伊州（芝加哥）常见做法整理，日期、税费以合同、律师和产权公司为准；其他州请在交易清单里自行增删。"),s("<b>HOA 规则、责任归属</b>各小区不同，以章程、物业服务合同或租约为准。"),s("<b>数据备份</b>：设置页可随时导出 JSON；云端版请勿关闭数据库的 RLS，anon key 可以公开但 service_role key 绝不能放进前端。"),s("<b>免费层数据库</b>长期无人访问可能被暂停，日常使用一般不会触发；久不用后打开慢一点属正常。"),s("<b>彻底删除房产</b>会连同它的账单、设备、季节任务、资料、交易一起删，不能恢复（花费统计保留）；平时用“归档”就够了。")])}</ul>`)}

      ${b(s("多人协作怎么工作"),`<ul class="about-notes">${t([s("家人在同一个“家庭”下，库存增减用数据库加锁，两个人同时点 −1 不会互相覆盖。"),s("购物车可以“我来买”认领，别人就不会重复买；已买到自动加回库存。"),s("季节任务、交易清单、缴费记录都记着“谁、什么时候”做的。"),s("家人名册（大人、孩子、宠物）全家共用，名字不能重复（忽略大小写和空格）；家庭成员会自动进名册，同名的会合并关联。"),s("家主（创建家庭的人，可多位）可以重置邀请码、改家人称呼、设 / 取消家主、移出误加入的人。")])}</ul>`)}

      ${o.length?b(s("姐妹站点"),`<p class="muted">${s("同一作者的其他小工具，顶栏站名旁的小胶囊可以直接切换：")}</p><ul class="app-list">${o.map(a=>`<li><span class="app-ico" aria-hidden="true">${a.icon}</span><div class="grow"><b>${l(s(a.name))}</b><small>${l(s(a.sub))}</small></div><a class="ui-btn" data-size="sm" href="${l(a.url)}">${s("打开")}</a></li>`).join("")}</ul>`):""}

      <p class="muted about-foot">${s("更多细节在仓库的 README 和 docs/ 设计文档里。")}
        <a href="https://github.com/dev-hyang/home-pantry" target="_blank" rel="noopener noreferrer">GitHub</a> · <a href="${u("me","settings")}">${s("设置")}</a></p>
    </section>`}export{f as viewAbout};
